import {validHalfEquation} from './half-equations.js?v=20261023-physicscomplete01';
export const cellPairs=[{id:'mgcu',left:'Mg',right:'Cu',voltage:1.6,donor:'left',count:2},{id:'zncu',left:'Zn',right:'Cu',voltage:.8,donor:'left',count:3},{id:'cumg',left:'Cu',right:'Mg',voltage:1.6,donor:'right',count:3}];
export const fuelChoices=[{id:'depot',title:'Overnight depot',prompt:'A depot has cheap overnight charging,8 hours idle each night, no hydrogen supply and no need for rapid refuelling.',technology:'battery',evidence:'charging'},{id:'fleet',title:'Fast turnaround',prompt:'A fleet has a reliable hydrogen delivery contract and short stops. Available battery charging would take longer than the stops; the supplied hydrogen refuelling time fits.',technology:'fuel',evidence:'turnaround'},{id:'impact',title:'Compare the system',prompt:'A supplier claims water-only exhaust proves its fuel-cell system has zero lifecycle emissions. No production or manufacturing data are supplied.',technology:'more',evidence:'lifecycle'}];
export const fuelHalfTasks=[{id:'acid-h',title:'Acidic hydrogen electrode',prompt:'H₂ forms H⁺ at the anode. Write the oxidation half-equation.',answer:'H2 -> 2H+ + 2e-'},{id:'acid-o',title:'Acidic oxygen electrode',prompt:'O₂ and H⁺ form water at the cathode. Write the reduction half-equation.',answer:'O2 + 4H+ + 4e- -> 2H2O'},{id:'alk-h',title:'Alkaline hydrogen electrode',prompt:'H₂ and OH⁻ form water at the anode. Write the oxidation half-equation.',answer:'H2 + 2OH- -> 2H2O + 2e-'}];
const near=(v,n)=>String(v??'').trim()!==''&&Number.isFinite(Number(v))&&Math.abs(Number(v)-n)<.01;
export function cellCorrect(t,a){return near(a.voltage,t.voltage)&&a.donor===t.donor&&near(a.total,t.voltage*t.count);}
export function fuelCorrect(t,a){return a.technology===t.technology&&a.evidence===t.evidence;}
export function fuelHalfCorrect(t,a){return validHalfEquation(a.equation,t.answer);}
